import csv, datetime, math, statistics
rows=list(csv.DictReader(open("data.csv")))
by={}
for r in rows:
    by.setdefault(r["band"],[]).append((datetime.date.fromisoformat(r["date"]),float(r["y"])))
for b in by: by[b].sort()

def doy(d): return d.timetuple().tm_yday

def design(dates, K, trend=False, t0=None):
    X=[]
    for d in dates:
        a=2*math.pi*doy(d)/365.25
        row=[1.0]
        for k in range(1,K+1):
            row += [math.cos(k*a), math.sin(k*a)]
        if trend:
            row.append((d-t0).days/365.25)
        X.append(row)
    return X

def solve(X,y):
    # normal equations
    n=len(X[0])
    A=[[sum(X[i][a]*X[i][b] for i in range(len(X))) for b in range(n)] for a in range(n)]
    bvec=[sum(X[i][a]*y[i] for i in range(len(X))) for a in range(n)]
    # gaussian elim
    for c in range(n):
        p=max(range(c,n),key=lambda r:abs(A[r][c]))
        A[c],A[p]=A[p],A[c]; bvec[c],bvec[p]=bvec[p],bvec[c]
        for r in range(n):
            if r!=c and A[c][c]!=0:
                f=A[r][c]/A[c][c]
                for k in range(c,n): A[r][k]-=f*A[c][k]
                bvec[r]-=f*bvec[c]
    return [bvec[i]/A[i][i] for i in range(n)]

def pred(beta,d,K,trend,t0):
    a=2*math.pi*doy(d)/365.25
    row=[1.0]
    for k in range(1,K+1): row+=[math.cos(k*a),math.sin(k*a)]
    if trend: row.append((d-t0).days/365.25)
    return sum(beta[i]*row[i] for i in range(len(row)))

# backtest: train on dates < 2023-09-21, test on last year
cut=datetime.date(2023,9,21)
for b in by:
    tr=[(d,v) for d,v in by[b] if d<cut]
    te=[(d,v) for d,v in by[b] if d>=cut]
    t0=tr[0][0]
    best=None
    for K in range(1,5):
        for trend in (False,True):
            X=design([d for d,_ in tr],K,trend,t0)
            beta=solve(X,[v for _,v in tr])
            err=[abs(pred(beta,d,K,trend,t0)-v) for d,v in te]
            mae=statistics.mean(err)
            if best is None or mae<best[0]: best=(mae,K,trend)
    print(b,"best MAE",round(best[0],3),"K",best[1],"trend",best[2])
