    if day>=pts[-1][0]: return pts[-1][1]
    for i in range(len(pts)-1):
        d0,v0=pts[i]; d1,v1=pts[i+1]
        if d0<=day<=d1:
            if d1==d0: return v0
            f=(day-d0).days/(d1-d0).days
            return v0+f*(v1-v0)
    return None

def clim_pred(pts, cutoff, d, win, recency):
    cand=[]; wts=[]
    for yr in range(pts[0][0].year, cutoff.year+1):
        for off in range(-win,win+1,3):
            dd=date(yr,d.month,d.day)+timedelta(days=off)
            if pts[0][0]<=dd<=cutoff:
                cand.append(interp(pts,dd))
                wts.append((1.0 if not recency else (0.5**(cutoff.year-yr))))
    if not cand: return interp(pts, d-timedelta(days=365))
    return sum(c*w for c,w in zip(cand,wts))/sum(wts)

def harm_fit(pts):
    X=[]; Y=[]
    for d,v in pts:
        t=(d-pts[0][0]).days
        X.append([1, math.cos(2*math.pi*t/365.25), math.sin(2*math.pi*t/365.25),
                  math.cos(4*math.pi*t/365.25), math.sin(4*math.pi*t/365.25), t])
        Y.append(v)
    p=6
    A=[[sum(X[k][i]*X[k][j] for k in range(len(X))) for j in range(p)] for i in range(p)]
    b=[sum(X[k][i]*Y[k] for k in range(len(X))) for i in range(p)]
    for c in range(p):
        piv=max(range(c,p),key=lambda r:abs(A[r][c]))
        A[c],A[piv]=A[piv],A[c]; b[c],b[piv]=b[piv],b[c]
        for r in range(p):
            if r==c: continue
            f=A[r][c]/A[c][c]
            for cc in range(c,p): A[r][cc]-=f*A[c][cc]
            b[r]-=f*b[c]
    return [b[i]/A[i][i] for i in range(p)], pts[0][0]

def backtest(band, cutoff, win, recency, blend):
    pts=[(d,v) for d,v in ser[band] if d<=cutoff]
    test=[(d,v) for d,v in ser[band] if d>cutoff]
    coef,t0=harm_fit(pts)
    def hp(d):
        t=(d-t0).days
        return (coef[0]+coef[1]*math.cos(2*math.pi*t/365.25)+coef[2]*math.sin(2*math.pi*t/365.25)
                +coef[3]*math.cos(4*math.pi*t/365.25)+coef[4]*math.sin(4*math.pi*t/365.25)+coef[5]*t)
    errs=[]
    for d,v in test:
        cl=clim_pred(pts,cutoff,d,win,recency)
        pr=(1-blend)*cl+blend*hp(d)
        errs.append(abs(pr-v))
    return statistics.fmean(errs)

