import csv, datetime, math
rows=list(csv.DictReader(open("data.csv")))
from collections import defaultdict
series=defaultdict(list); dates={}
for r in rows:
    series[r["band"]].append(float(r["y"])); dates[r["period_id"]]=r["date"]
pids=sorted(dates)
ds=[datetime.date.fromisoformat(dates[p]) for p in pids]

def seasonal_forecast(train_ds, train_y, fut_ds, mode="month"):
    # month-of-year mean, optionally with linear trend on deseasonalized
    bym=defaultdict(list)
    for d,v in zip(train_ds,train_y): bym[d.month].append(v)
    gm=sum(train_y)/len(train_y)
    seas={m:sum(v)/len(v) for m,v in bym.items()}
    out=[]
    for d in fut_ds:
        s=seas.get(d.month, gm)
        out.append(s)
    return out

def seasonal_trend(train_ds, train_y, fut_ds):
    bym=defaultdict(list)
    for d,v in zip(train_ds,train_y): bym[d.month].append(v)
    gm=sum(train_y)/len(train_y)
    seas={m:sum(v)/len(v)-gm for m,v in bym.items()}
    des=[v-seas.get(d.month,0) for d,v in zip(train_ds,train_y)]
    n=len(des); xs=list(range(n)); mx=sum(xs)/n; my=sum(des)/n
    b1=sum((xs[i]-mx)*(des[i]-my) for i in range(n))/sum((x-mx)**2 for x in xs)
    b0=my-b1*mx
    out=[]
    for i,d in enumerate(fut_ds):
        out.append(b0+b1*(n+i)+seas.get(d.month,0))
    return out

def mae(a,b): return sum(abs(a[i]-b[i]) for i in range(len(a)))/len(a)

for H in [12,27,40]:
    print("=== H",H)
    for b in series:
        y=series[b]
        tr_ds=ds[:-H]; tr_y=y[:-H]; te_ds=ds[-H:]; te_y=y[-H:]
        s=seasonal_forecast(tr_ds,tr_y,te_ds)
        st=seasonal_trend(tr_ds,tr_y,te_ds)
        print(b,"seasonal",round(mae(s,te_y),3),"seas+trend",round(mae(st,te_y),3))
