    d=doy(p); row=[1.0]
    if trend: row.append(tday(p)/365.0)
    for k in range(1,K+1):
        row.append(math.sin(2*math.pi*k*d/365.25)); row.append(math.cos(2*math.pi*k*d/365.25))
    return sum(c*x for c,x in zip(coef,row))

def analog_pred(train_ps, ys_map, p, win=10):
