import csv, datetime, math, statistics
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
by_band=defaultdict(list)
for r in rows:
    by_band[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in by_band: by_band[b].sort()
def doy(d): return d.timetuple().tm_yday

def design(dates, t0, harmonics, trend):
    X=[]
    for d in dates:
        ang=2*math.pi*doy(d)/365.25
        row=[1.0]
        for h in range(1,harmonics+1):
            row.append(math.cos(h*ang)); row.append(math.sin(h*ang))
        if trend: row.append((d-t0).days/365.25)
        X.append(row)
    return X
def solve(A,b):
    n=len(A); p=len(A[0])
    M=[[sum(A[k][i]*A[k][j] for k in range(n)) for j in range(p)] for i in range(p)]
    v=[sum(A[k][i]*b[k] for k in range(n)) for i in range(p)]
    for i in range(p): M[i][i]+=1e-9
    for c in range(p):
        piv=max(range(c,p),key=lambda r:abs(M[r][c]))
        M[c],M[piv]=M[piv],M[c]; v[c],v[piv]=v[piv],v[c]
        for r in range(p):
            if r==c: continue
            f=M[r][c]/M[c][c]
            for cc in range(c,p): M[r][cc]-=f*M[c][cc]
            v[r]-=f*v[c]
    return [v[i]/M[i][i] for i in range(p)]

def harmonic(train, test_dates, harmonics=2, trend=True, robust=True):
    dates=[d for d,_ in train]; y=[v for _,v in train]
    t0=dates[0]
    X=design(dates,t0,harmonics,trend)
    beta=solve(X,y)
    if robust:
        for _ in range(20):
            res=[y[i]-sum(X[i][j]*beta[j] for j in range(len(beta))) for i in range(len(y))]
            s=statistics.median([abs(r) for r in res])*1.4826+1e-9
            w=[1.0/(1.0+(r/(2.0*s))**2) for r in res]
            Xw=[[X[i][j]*math.sqrt(w[i]) for j in range(len(beta))] for i in range(len(y))]
            yw=[y[i]*math.sqrt(w[i]) for i in range(len(y))]
            beta=solve(Xw,yw)
    Xt=design(test_dates,t0,harmonics,trend)
    return [sum(Xt[i][j]*beta[j] for j in range(len(beta))) for i in range(len(test_dates))]

def seasonal_median(train, test_dates, halfwin=25):
    dates=[d for d,_ in train]; y=[v for _,v in train]
    out=[]
    for td in test_dates:
        dd=doy(td); rs=[]
        for i,d in enumerate(dates):
            diff=abs(doy(d)-dd); diff=min(diff,365.25-diff)
            if diff<=halfwin: rs.append(y[i])
        out.append(statistics.median(rs) if rs else statistics.median(y))
    return out

def seasonal_mean_trim(train, test_dates, halfwin=25):
    dates=[d for d,_ in train]; y=[v for _,v in train]
    out=[]
    for td in test_dates:
        dd=doy(td); rs=[]
        for i,d in enumerate(dates):
            diff=abs(doy(d)-dd); diff=min(diff,365.25-diff)
            if diff<=halfwin: rs.append(y[i])
        if rs:
            rs.sort()
            k=max(1,int(len(rs)*0.2))
            rs=rs[k:len(rs)-k] if len(rs)>2*k else rs
