rows=list(csv.DictReader(open("data.csv")))
data=defaultdict(list)
for r in rows:
    data[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in data: data[b].sort()
periods=sorted(set(d for b in data for d,_ in data[b]))
cut=periods[-52]
def doy(d): return d.timetuple().tm_yday

def clim(train, td, bw):
    dt=doy(td); num=den=0.0
    for d,v in train:
        dd=abs(doy(d)-dt); dd=min(dd,365-dd)
        w=math.exp(-0.5*(dd/bw)**2); num+=w*v; den+=w
    return num/den if den>0 else statistics.fmean([v for _,v in train])

def linfit(train):
    t0=train[0][0]
    xs=[(d-t0).days/365.25 for d,_ in train]; ys=[v for _,v in train]
    n=len(xs); mx=statistics.fmean(xs); my=statistics.fmean(ys)
    sxx=sum((x-mx)**2 for x in xs); sxy=sum((x-mx)*(ys[i]-my) for i,x in enumerate(xs))
    b=sxy/sxx if sxx>0 else 0; a=my-b*mx
    return a,b,t0

def run(bw, use_trend):
    per={}
    for b in sorted(data):
        series=data[b]; train=[(d,v) for d,v in series if d<cut]; test=[(d,v) for d,v in series if d>=cut]
        if use_trend:
            a,sl,t0=linfit(train)
            res=[(d, v-(a+sl*(d-t0).days/365.25)) for d,v in train]
            preds=[clim(res,d,bw)+a+sl*(d-t0).days/365.25 for d,v in test]
        else:
            preds=[clim(train,d,bw) for d,v in test]
        per[b]=statistics.fmean(abs(p-v) for p,(_,v) in zip(preds,test))
    return per

for bw in [3,5,7,10]:
