def seasonal_analog(pts, target_doy, target_year, window=20, halflife_years=2.0):
    # weighted average of past values within window of doy, recency weighted
    num=den=0.0
    for d,dd,v in pts:
        if d.year>=target_year: continue
        if dcirc(dd,target_doy)<=window:
            w=math.exp(-(target_year-d.year)/halflife_years)*math.exp(-0.5*(dcirc(dd,target_doy)/window)**2)
            num+=w*v; den+=w
    if den==0: return None
    return num/den

def harmonic(pts, target_doy, target_year, K=2):
    # fit y = a0 + a1*t + sum fourier; t in years
    n=len(pts)
    t0=pts[0][0]
    feats=[]
    ys=[]
    for d,dd,v in pts:
        t=(d-t0).days/365.25
        ang=2*math.pi*dd/365.25
        row=[1.0,t]
        for k in range(1,K+1):
            row.append(math.sin(k*ang)); row.append(math.cos(k*ang))
        feats.append(row); ys.append(v)
    p=len(feats[0])
    # normal equations
    A=[[0.0]*p for _ in range(p)]; b=[0.0]*p
    for f,y in zip(feats,ys):
        for i in range(p):
            b[i]+=f[i]*y
            for j in range(p): A[i][j]+=f[i]*f[j]
    for i in range(p): A[i][i]+=1e-6
    # gaussian elim
    for c in range(p):
        piv=max(range(c,p),key=lambda r:abs(A[r][c]))
        A[c],A[piv]=A[piv],A[c]; b[c],b[piv]=b[piv],b[c]
        for r in range(p):
