    n=len(A[0])
    AtA=[[sum(A[k][i]*A[k][j] for k in range(len(A))) for j in range(n)] for i in range(n)]
    Aty=[sum(A[k][i]*y[k] for k in range(len(A))) for i in range(n)]
    for i in range(n): AtA[i][i]+=1e-9
    # gaussian elim
    M=[row[:]+[Aty[i]] for i,row in enumerate(AtA)]
    for c in range(n):
        p=max(range(c,n),key=lambda r:abs(M[r][c])); M[c],M[p]=M[p],M[c]
        pv=M[c][c]
        for j in range(c,n+1): M[c][j]/=pv
        for r in range(n):
            if r!=c and M[r][c]!=0:
                f=M[r][c]
                for j in range(c,n+1): M[r][j]-=f*M[c][j]
    return [M[i][n] for i in range(n)]

