    if t>=xs[-1]: return ys[-1]
    i=bisect.bisect_left(xs,t)
    if xs[i]==t: return ys[i]
    x0,x1=xs[i-1],xs[i]; y0,y1=ys[i-1],ys[i]
    return y0+(y1-y0)*(t-x0)/(x1-x0)

