import csv, datetime, math, statistics
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
by=defaultdict(list)
for r in rows:
    by[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in by: by[b].sort()
def doy(d): return d.timetuple().tm_yday

def solve(A,bv):
    n=len(bv); A=[row[:] for row in A]; bv=bv[:]
    for c in range(n):
        p=max(range(c,n),key=lambda r:abs(A[r][c])); A[c],A[p]=A[p],A[c]; bv[c],bv[p]=bv[p],bv[c]
        if abs(A[c][c])<1e-12: continue
        for r in range(n):
            if r!=c:
                f=A[r][c]/A[c][c]
                for k in range(c,n): A[r][k]-=f*A[c][k]
                bv[r]-=f*bv[c]
    return [bv[i]/A[i][i] if abs(A[i][i])>1e-12 else 0 for i in range(n)]

def fourier_pred(train,tdates,K,trend):
    t0=train[0][0]
    def feats(d):
        x=[1.0]; ang=2*math.pi*doy(d)/365.25
        for k in range(1,K+1): x+=[math.sin(k*ang),math.cos(k*ang)]
        if trend: x.append((d-t0).days/365.25)
        return x
    X=[feats(d) for d,y in train]; Y=[y for d,y in train]; n=len(X[0])
    A=[[sum(X[i][a]*X[i][b] for i in range(len(X))) for b in range(n)] for a in range(n)]
    bv=[sum(X[i][a]*Y[i] for i in range(len(X))) for a in range(n)]
    coef=solve(A,bv)
    return [sum(c*f for c,f in zip(coef,feats(td))) for td in tdates]

def analog_pred(train,tdates,win):
    out=[]
    for td in tdates:
        vals=[]
        for d,y in train:
            dd=abs(doy(d)-doy(td)); dd=min(dd,365-dd)
            if dd<=win: vals.append(y)
        out.append(sum(vals)/len(vals) if vals else None)
    return out

cuts=[datetime.date(2022,9,22),datetime.date(2023,3,22),datetime.date(2023,9,22),datetime.date(2024,3,22)]
methods={}
for w in [8,10,12,15,18,20,25]:
    methods[f"an{w}"]=lambda tr,td,w=w:analog_pred(tr,td,w)
# blends
for w in [12,15,18]:
    for K in [4,5]:
        methods[f"blend_an{w}_f{K}"]=lambda tr,td,w=w,K=K:[0.5*a+0.5*f for a,f in zip(analog_pred(tr,td,w),fourier_pred(tr,td,K,False))]

agg=defaultdict(list)
perband=defaultdict(lambda:defaultdict(list))
for b in by:
    sd=statistics.pstdev([y for d,y in by[b]])
    for cut in cuts:
        train=[(d,y) for d,y in by[b] if d<cut]
        test=[(d,y) for d,y in by[b] if cut<=d<cut+datetime.timedelta(days=365)]
        if len(train)<30 or len(test)<5: continue
        tdates=[d for d,y in test]; actual=[y for d,y in test]
        for name,fn in methods.items():
            pred=fn(train,tdates)
            pairs=[(p,a) for p,a in zip(pred,actual) if p is not None]
            if not pairs: continue
            mae=sum(abs(p-a) for p,a in pairs)/len(pairs)/sd
            agg[name].append(mae); perband[b][name].append(mae)
print("Multi-fold normalized MAE:")
for name in sorted(agg,key=lambda c:sum(agg[c])/len(agg[c])):
    print(f"{name:18s}", round(sum(agg[name])/len(agg[name]),4))
print("\nBest per band:")
for b in perband:
    best=min(perband[b],key=lambda n:sum(perband[b][n])/len(perband[b][n]))
    print(b, best, round(sum(perband[b][best])/len(perband[b][best]),4))
