for r in rows: d[r["band"]][r["period_id"]]=float(r["y"])
D=[datetime.date.fromisoformat(dates[p]) for p in periods]

def interp_at(b, target):
    # linear interpolate band b at target date using observations bracketing it
    xs=[D[i].toordinal() for i in range(len(D))]
    ys=[d[b][periods[i]] for i in range(len(D))]
    t=target.toordinal()
    if t<=xs[0]: return ys[0]
    if t>=xs[-1]: return ys[-1]
    for i in range(len(xs)-1):
        if xs[i]<=t<=xs[i+1]:
            f=(t-xs[i])/(xs[i+1]-xs[i])
            return ys[i]+f*(ys[i+1]-ys[i])
    return ys[-1]

def seasonal_pred(b, target, years_back, ref_year):
    # average interpolated values at same day-of-year in prior years
    vals=[]
    for yb in years_back:
        try:
            td=target.replace(year=target.year-yb)
        except ValueError:
            td=target.replace(year=target.year-yb, day=28)
