import csv, datetime, statistics, math
rows=list(csv.DictReader(open("data.csv")))
bands=['B2','B3','B4','B8','B11','B12','NDVI','NDWI']
periods=[]; seen=set(); dates={}
for r in rows:
    if r["period_id"] not in seen:
        seen.add(r["period_id"]); periods.append(r["period_id"]); dates[r["period_id"]]=r["date"]
d={b:{} for b in bands}
for r in rows: d[r["band"]][r["period_id"]]=float(r["y"])
D=[datetime.date.fromisoformat(dates[p]) for p in periods]

def doy(dt): return dt.timetuple().tm_yday

def design(dt, K, trend):
    t=doy(dt)/365.25*2*math.pi
    row=[1.0]
    for k in range(1,K+1):
        row.append(math.sin(k*t)); row.append(math.cos(k*t))
    if trend: row.append(dt.toordinal()/365.25)
    return row

def solve(A,y):
    # normal equations
    n=len(A[0])
    AtA=[[sum(A[i][a]*A[i][b] for i in range(len(A))) for b in range(n)] for a in range(n)]
    Aty=[sum(A[i][a]*y[i] for i in range(len(A))) for a in range(n)]
    # gaussian elim
    M=[AtA[i][:]+[Aty[i]] for i in range(n)]
    for c in range(n):
        p=max(range(c,n),key=lambda r:abs(M[r][c]))
        M[c],M[p]=M[p],M[c]
        if abs(M[c][c])<1e-12: continue
        for r in range(n):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n]/M[i][i] if abs(M[i][i])>1e-12 else 0 for i in range(n)]

cut=datetime.date(2023,9,3)
train=[i for i in range(len(D)) if D[i]<cut]
test=[i for i in range(len(D)) if D[i]>=cut]

for b in bands:
    y=[d[b][periods[i]] for i in train]
    best=None
    for K in [1,2,3,4]:
        for trend in [False,True]:
            A=[design(D[i],K,trend) for i in train]
            coef=solve(A,y)
            errs=[abs(sum(coef[j]*design(D[i],K,trend)[j] for j in range(len(coef)))-d[b][periods[i]]) for i in test]
            mae=statistics.mean(errs)
            if best is None or mae<best[0]: best=(mae,K,trend)
    # persistence
    perr=statistics.mean([abs(d[b][periods[train[-1]]]-d[b][periods[i]]) for i in test])
