for r in rows:
    if r["period_id"] not in seen:
        seen.add(r["period_id"]); periods.append(r["period_id"]); dates[r["period_id"]]=r["date"]
d={b:{} for b in bands}
for r in rows: d[r["band"]][r["period_id"]]=float(r["y"])
D=[datetime.date.fromisoformat(dates[p]) for p in periods]
def doy(dt): return dt.timetuple().tm_yday

def circ_dist(a,b):
    diff=abs(a-b)%365.25
    return min(diff,365.25-diff)

def kernel_pred(train,b,target_doy,h,trend_adj):
    # trend_adj: subtract linear trend in time before smoothing
    xs=[D[i].toordinal() for i in train]
    ys=[d[b][periods[i]] for i in train]
    if trend_adj:
        n=len(xs); mx=sum(xs)/n; my=sum(ys)/n
        sxx=sum((x-mx)**2 for x in xs); sxy=sum((xs[i]-mx)*(ys[i]-my) for i in range(n))
        slope=sxy/sxx if sxx>0 else 0
        ys=[ys[i]-slope*(xs[i]-mx) for i in range(n)]
    td=doy(target_doy)
    num=0; den=0
    for i in train:
        dd=circ_dist(doy(D[i]),td)
        w=math.exp(-0.5*(dd/h)**2)
        num+=w*ys[i]; den+=w
    val=num/den if den>0 else statistics.mean(ys)
    if trend_adj:
        # extrapolate trend to target
        tx=target_doy.toordinal() if hasattr(target_doy,'toordinal') else None
        val+=slope*(tx-mx)
    return val

