rows=list(csv.DictReader(open("data.csv")))
periods=[]; seen=set()
for r in rows:
    if r["period_id"] not in seen: seen.add(r["period_id"]); periods.append(r["period_id"])
dates={r["period_id"]:datetime.date.fromisoformat(r["date"]) for r in rows}
by={}
for r in rows: by.setdefault(r["band"],{})[r["period_id"]]=float(r["y"])
bands=sorted(by)

def doy(d): return d.timetuple().tm_yday

# Validation: predict year-4 (dates >= 2023-09-25) using years 1-3
cut=datetime.date(2023,9,25)
train=[p for p in periods if dates[p]<cut]
test=[p for p in periods if dates[p]>=cut]
print("train",len(train),"test",len(test))

def predict_doy(band, target_date, train_periods, window):
    td=doy(target_date)
    vals=[]
    for p in train_periods:
        dd=doy(dates[p])
        diff=abs(dd-td); diff=min(diff,365-diff)
        if diff<=window:
            vals.append(by[band][p])
    if not vals: return None
    return statistics.median(vals)

for window in [7,10,14,21]:
    errs=[]
    for b in bands:
        for p in test:
            pred=predict_doy(b,dates[p],train,window)
            if pred is not None:
                errs.append(abs(pred-by[b][p]))
    print("window",window,"MAE",round(statistics.mean(errs),4),"n",len(errs))
