```bash
cat > cv2.py <<'PY'
import csv, datetime, statistics, math
from collections import defaultdict
rows=list(csv.DictReader(open('data.csv')))
seen={}
for r in rows: seen.setdefault(r['period_id'],r['date'])
ser=defaultdict(dict)
for r in rows: ser[r['band']][r['period_id']]=float(r['y'])
pids=sorted(seen); bands=sorted(ser)
def date(p): return datetime.date.fromisoformat(seen[p])
def doy(p): return date(p).timetuple().tm_yday
def year(p): return date(p).year
med={b:statistics.median(ser[b].values()) for b in bands}
def is_outlier(p):
    return sum(1 for b in bands if ser[b][p]>2.5*med[b] and med[b]>0)>=3
clean=[p for p in pids if not is_outlier(p)]

def doy_dist(a,b):
    d=abs(a-b)%365.25
    return min(d,365.25-d)

def knn_predict(b, train, target_doy, k, bw=None):
    # weighted average of train points by day-of-year distance
    ds=[(doy_dist(doy(p),target_doy), ser[b][p]) for p in train]
    ds.sort()
    if bw is None:
        sel=ds[:k]
        return statistics.mean(v for _,v in sel)
    else:
        num=sum(v*math.exp(-0.5*(d/bw)**2) for d,v in ds)
        den=sum(math.exp(-0.5*(d/bw)**2) for d,v in ds)
        return num/den if den>0 else statistics.mean(v for _,v in ds)

def eval_method(fn):
    errs=[]
    for yr in [2021,2022,2023]:
        tr=[p for p in clean if year(p)!=yr]
        te=[p for p in clean if year(p)==yr]
        for b in bands:
            sd=statistics.pstdev([ser[b][q] for q in clean])+1e-9
            for p in te:
                errs.append(abs(fn(b,tr,doy(p))-ser[b][p])/sd)
    return statistics.mean(errs)

for k in [3,5,8,12]:
    print('knn k=',k, round(eval_method(lambda b,tr,td,k=k: knn_predict(b,tr,td,k)),4))
for bw in [10,20,30,45,60]:
    print('kernel bw=',bw, round(eval_method(lambda b,tr,td,bw=bw: knn_predict(b,tr,td,None,bw)),4))
